import { pool } from "./pool";

/** Tagged template: each ${value} becomes a bound parameter. Nest sql`...` fragments to compose a query. */
export function sql(strings: TemplateStringsArray, ...values: unknown[]): Query {
  return new Query(strings, values);
}

/** Runs on the pool when awaited and resolves to the rows. */
export class Query implements PromiseLike<unknown[]> {
  constructor(readonly strings: TemplateStringsArray, readonly values: unknown[]) {}
  then<A, B>(ok?: (rows: unknown[]) => A, err?: (e: unknown) => B) {
    return pool.query(this.text(), this.params()).then((r) => r.rows).then(ok, err);
  }
  // text() and params() flatten nested fragments into $1..$n.
}

