import { query } from "../db/query";
import { buildExport } from "../exports/exportBuilder";
import { flags } from "../flags";
import { router } from "../router";
import { toCsv } from "../csv";

// Custom CSV exports: the user picks columns, filters and joins in the export dialog.
router.post("/exports", async (req, res) => {
  if (!flags.enabled("custom-exports", req.user)) return res.status(404).end();
  // buildExport() concatenates the chosen columns, filters and joins into one SQL string.
  const text = buildExport(req.body);
  res.type("text/csv").send(toCsv(await query(text)));
});

